import React from 'react'

function RandomPokemonRerollButton() {
  const DAILY_KEY = 'dailyPokemon'

  // Generate a new random Pokémon image
  const rerollPokemon = () => {
    window.location.reload()
  }

  return (
    <div className='p-8 text-center'>
      <button
        onClick={rerollPokemon}
        className='px-4 py-2 bg-blue-light text-white rounded-lg hover:bg-blue-dark'
      >
        Reroll Pokémon
      </button>
    </div>
  )
}

export default RandomPokemonRerollButton
